INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8301, '\(1\ \text{mm}\) ស្មើនឹងប៉ុន្មានម៉ែត្រ?', NULL, '["\\(10^{3}\\ \\text{m}\\)", "\\(10^{-2}\\ \\text{m}\\)", "\\(10^{-3}\\ \\text{m}\\)", "\\(10^{-1}\\ \\text{m}\\)"]', 2, NULL, 1, 'mcq', '\(1\ \text{mm} = 0.001\ \text{m}\)។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8302, 'ក្រដាស \(80\ \text{g/m}^2\) មានន័យថា៖', NULL, '["ក្រដាស ១ សន្លឹកមានម៉ាស \\(80\\ \\text{g}\\)", "ក្រដាស \\(80\\ \\text{m}^2\\) មានម៉ាស \\(1\\ \\text{g}\\)", "កម្រាស់ក្រដាស \\(80\\ \\text{mm}\\)", "ក្រដាស \\(1\\ \\text{m}^2\\) មានម៉ាស \\(80\\ \\text{g}\\)"]', 3, NULL, 1, 'mcq', 'ម៉ាសធៀបនឹងផ្ទៃក្រឡាគឺម៉ាសក្នុង \(1\ \text{m}^2\)។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8303, 'រូបមន្តល្បឿនមធ្យមគឺ៖', NULL, '["\\(v = \\dfrac{d}{t}\\)", "\\(v = d + t\\)", "\\(v = \\dfrac{t}{d}\\)", "\\(v = d \\times t\\)"]', 0, NULL, 1, 'mcq', 'ល្បឿន = ចម្ងាយចរ ÷ រយៈពេល។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8304, 'រូបមន្តផ្ទៃក្រឡាមុខកាត់ស៊ីឡាំងដែលមានអង្កត់ផ្ចិត \(d\) គឺ៖', NULL, '["\\(\\mathcal{A} = \\pi d^2\\)", "\\(\\mathcal{A} = \\dfrac{\\pi d}{4}\\)", "\\(\\mathcal{A} = 2\\pi d\\)", "\\(\\mathcal{A} = \\dfrac{\\pi d^2}{4}\\)"]', 3, NULL, 1, 'mcq', 'មុខកាត់ជារង្វង់ \(\mathcal{A} = \pi r^2 = \dfrac{\pi d^2}{4}\)។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8305, '\(1\ \text{g/cm}^3\) ស្មើនឹងប៉ុន្មាន \(\text{kg/m}^3\)?', NULL, '["\\(0.001\\ \\text{kg/m}^3\\)", "\\(1\\ \\text{kg/m}^3\\)", "\\(1\\,000\\ \\text{kg/m}^3\\)", "\\(100\\ \\text{kg/m}^3\\)"]', 2, NULL, 1, 'mcq', '\(\dfrac{10^{-3}\ \text{kg}}{(10^{-2}\ \text{m})^3} = 1\,000\ \text{kg/m}^3\)។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8306, 'រថភ្លើងធ្វើដំណើរ \(3\) ម៉ោង ដោយល្បឿន \(30\ \text{km/h}\)។ ចម្ងាយចរ៖', NULL, '["\\(33\\ \\text{km}\\)", "\\(90\\ \\text{km}\\)", "\\(27\\ \\text{km}\\)", "\\(10\\ \\text{km}\\)"]', 1, NULL, 1, 'mcq', '\(30 \times 3 = 90\)។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8307, 'មាឌស៊ីឡាំងមានអង្កត់ផ្ចិត \(d\) និងប្រវែង \(l\) គឺ៖', NULL, '["\\(V = \\pi d \\times l\\)", "\\(V = \\dfrac{\\pi d^2}{4} \\times l\\)", "\\(V = \\dfrac{\\pi d^2}{4} + l\\)", "\\(V = \\dfrac{\\pi d}{4} \\times l\\)"]', 1, NULL, 1, 'mcq', 'មាឌ = ផ្ទៃក្រឡាមុខកាត់ × ប្រវែង។', 'រង្វាស់រង្វាល់', 'easy', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
