INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8322, 'សំឡេងធ្វើដំណើរ \(343\ \text{m/s}\)។ ក្នុង \(1\) នាទី សំឡេងធ្វើដំណើរបាន៖', NULL, '["\\(20.58\\ \\text{km}\\)", "\\(2.058\\ \\text{km}\\)", "\\(343\\ \\text{km}\\)", "\\(5.72\\ \\text{km}\\)"]', 0, NULL, 2, 'mcq', '\(343 \times 60 = 20\,580\ \text{m}\)។', 'រង្វាស់រង្វាល់', 'medium', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-25f6de3e4d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8323, 'ខ្សែភ្លើងរាងស៊ីឡាំងមានអង្កត់ផ្ចិត \(1.2\ \text{mm}\)។ គណនាផ្ទៃក្រឡាមុខកាត់គិតជា \(\text{m}^2\) (យក \(\pi = 3.14\))៖', 'g8-25f6de3e4d.svg', '["\\(1.1304\\times10^{-5}\\ \\text{m}^{2}\\)", "\\(4.5216\\times10^{-6}\\ \\text{m}^{2}\\)", "\\(1.1304\\times10^{-7}\\ \\text{m}^{2}\\)", "\\(1.1304\\times10^{-6}\\ \\text{m}^{2}\\)"]', 3, NULL, 2, 'mcq', '\(\mathcal{A} = \dfrac{3.14 \times (1.2\times10^{-3})^2}{4}\) \(= 1.1304\times10^{-6}\ \text{m}^2\)។', 'រង្វាស់រង្វាល់', 'medium', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
