INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8324, 'សរសៃដែកមានអង្កត់ផ្ចិត \(24\ \text{mm}\) ប្រវែង \(10\ \text{m}\)។ មាឌគិតជា \(\text{m}^3\) (យក \(\pi = 3.14\))៖', 'g8-ef90991657.svg', '["\\(1.80864\\times10^{-2}\\ \\text{m}^{3}\\)", "\\(4.5216\\times10^{-4}\\ \\text{m}^{3}\\)", "\\(4.5216\\times10^{-3}\\ \\text{m}^{3}\\)", "\\(4.5216\\times10^{-2}\\ \\text{m}^{3}\\)"]', 2, NULL, 2, 'mcq', '\(V = \dfrac{3.14 \times 576\times10^{-6}}{4} \times 10 = 4\,521.6\times10^{-6}\ \text{m}^3\)។', 'រង្វាស់រង្វាល់', 'medium', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8325, 'ខ្សែភ្លើងមួយមានផ្ទៃក្រឡាមុខកាត់ \(\dfrac{\pi}{4} \times 10^{-6}\ \text{m}^2\)។ អង្កត់ផ្ចិតគឺ៖', NULL, '["\\(2\\ \\text{mm}\\)", "\\(10\\ \\text{mm}\\)", "\\(0.1\\ \\text{mm}\\)", "\\(1\\ \\text{mm}\\)"]', 3, NULL, 3, 'mcq', '\(d = \sqrt{\dfrac{4\mathcal{A}}{\pi}} = \sqrt{10^{-6}} = 10^{-3}\ \text{m}\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
