INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8326, 'ឈើជ្រុងមួយដើមមានមុខកាត់ \(4\ \text{cm} \times 8\ \text{cm}\) ប្រវែង \(4.5\ \text{m}\)។ ទិញ \(50\) ដើម ឈើ \(1\ \text{m}^3\) ថ្លៃ \(1\,200\,000\) ៛។ ត្រូវចំណាយ៖', 'g8-c3040df34e.svg', '["\\(8\\,640\\,000\\) ៛", "\\(17\\,280\\) ៛", "\\(86\\,400\\) ៛", "\\(864\\,000\\) ៛"]', 3, NULL, 3, 'mcq', '\(V = 50 \times 0.0144 = 0.72\ \text{m}^3\) ; \(0.72 \times 1\,200\,000 = 864\,000\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8327, 'ក្រដាសរ៉ាម ១ ដុំមាន \(500\) សន្លឹក ខ្នាត \(210\ \text{mm}\times297\ \text{mm}\) ម៉ាសធៀបនឹងផ្ទៃក្រឡា \(80\ \text{g/m}^2\)។ ម៉ាសរ៉ាមមួយប្រហែល៖', NULL, '["\\(4.99\\ \\text{kg}\\)", "\\(0.25\\ \\text{kg}\\)", "\\(2.5\\ \\text{kg}\\)", "\\(25\\ \\text{kg}\\)"]', 2, NULL, 3, 'mcq', '\(500 \times 4.9896\ \text{g} = 2\,494.8\ \text{g} \approx 2.5\ \text{kg}\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8328, 'វិបុលជិះកង់ \(26\ \text{km}\) ក្នុង \(41\ \text{mn}\ 52\ \text{s}\)។ ល្បឿនមធ្យមប្រហែល៖', NULL, '["\\(0.62\\ \\text{km/h}\\)", "\\(26.6\\ \\text{km/h}\\)", "\\(45.1\\ \\text{km/h}\\)", "\\(37.26\\ \\text{km/h}\\)"]', 3, NULL, 3, 'mcq', '\(2\,512\ \text{s} = \dfrac{157}{225}\ \text{h}\) ; \(26 \times \dfrac{225}{157} \approx 37.26\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8329, 'ក្រដាសដើមម៉ាស \(70\ \text{g/m}^2\) កាត់ជារ៉ាម ខ្នាត \(210\ \text{mm}\times297\ \text{mm}\) (\(500\) សន្លឹក) ខាតចំនៀរ \(4\%\) (ផ្ទៃខាតបូកបន្ថែម \(4\%\) នៃផ្ទៃរ៉ាម)។ ម៉ាសក្រដាសត្រូវប្រើ ១ រ៉ាមប្រហែល៖', NULL, '["\\(3.2\\ \\text{kg}\\)", "\\(2.8\\ \\text{kg}\\)", "\\(2.3\\ \\text{kg}\\)", "\\(2.2\\ \\text{kg}\\)"]', 2, NULL, 3, 'mcq', '\(31.185 \times 1.04 = 32.4324\ \text{m}^2\) ; \(\times 70 = 2\,270.268\ \text{g} \approx 2.3\ \text{kg}\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8330, 'យន្តហោះហោះ \(575\ \text{km/h}\) ចម្ងាយ \(1\,700\ \text{km}\)។ រយៈពេលប្រហែល៖', NULL, '["\\(3\\ \\text{h}\\ 30\\ \\text{mn}\\)", "\\(2\\ \\text{h}\\ 22\\ \\text{mn}\\)", "\\(2\\ \\text{h}\\ 57\\ \\text{mn}\\)", "\\(2\\ \\text{h}\\ 9\\ \\text{mn}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{1\,700}{575} = \dfrac{68}{23} \approx 2.9565\ \text{h}\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
