INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8331, 'ដែក \(14\) លី ប្រវែង \(12\ \text{m}\) ម៉ាសមាឌ \(7\,874\ \text{kg/m}^3\) (\(\pi=3.14\))។ ម៉ាសប្រហែល៖', 'g8-5d2709361c.svg', '["\\(1.5\\ \\text{kg}\\)", "\\(14.5\\ \\text{kg}\\)", "\\(58.2\\ \\text{kg}\\)", "\\(145.4\\ \\text{kg}\\)"]', 1, NULL, 3, 'mcq', '\(m = \dfrac{3.14 \times 196\times10^{-6}}{4} \times 12 \times 7\,874 \approx 14.5\ \text{kg}\)។', 'រង្វាស់រង្វាល់', 'hard', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8332, 'ពពកមួយរសាត់ពីព្រះសីហនុមកភ្នំពេញ ចម្ងាយ \(230\ \text{km}\) ខ្យល់ល្បឿន \(6\ \text{m/s}\)។ រយៈពេលប្រហែល៖', NULL, '["\\(38.3\\ \\text{h}\\)", "\\(10\\ \\text{h}\\ 39\\ \\text{mn}\\)", "\\(1\\ \\text{h}\\ 39\\ \\text{mn}\\)", "\\(13\\ \\text{h}\\ 50\\ \\text{mn}\\)"]', 1, NULL, 3, 'mcq', '\(6\ \text{m/s} = 21.6\ \text{km/h}\) ; \(\dfrac{230}{21.6} \approx 10.65\ \text{h}\)។', 'រង្វាស់រង្វាល់', 'pisa', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8333, 'រតនាត្រូវដល់សាលា \(15\) នាទីមុន \(7\ \text{h}\ 00\)។ ផ្ទះឆ្ងាយ \(800\ \text{m}\) ដើរ \(5\ \text{km/h}\)។ ត្រូវចេញពីផ្ទះនៅម៉ោង៖', NULL, '["\\(6\\ \\text{h}\\ 35\\ \\text{mn}\\ 24\\ \\text{s}\\)", "\\(6\\ \\text{h}\\ 45\\ \\text{mn}\\)", "\\(6\\ \\text{h}\\ 29\\ \\text{mn}\\)", "\\(6\\ \\text{h}\\ 50\\ \\text{mn}\\)"]', 0, NULL, 3, 'mcq', '\(6\ \text{h}\ 45 - 9\ \text{mn}\ 36\ \text{s}\)។', 'រង្វាស់រង្វាល់', 'pisa', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8334, 'សៀវភៅមួយក្បាល \(100\) ទំព័រ ខ្នាត \(148\ \text{mm}\times210\ \text{mm}\) ម៉ាសក្រដាសសាច់ក្នុង \(70\ \text{g/m}^2\) (ទំព័រ \(100\) = \(50\) សន្លឹក \(= 50\times 0.03108\ \text{m}^2\))។ ម៉ាសសាច់ក្នុង ១ ក្បាល៖', NULL, '["\\(217.56\\ \\text{g}\\)", "\\(155.4\\ \\text{g}\\)", "\\(108.78\\ \\text{g}\\)", "\\(10.878\\ \\text{g}\\)"]', 2, NULL, 3, 'mcq', '\(50 \times 0.03108 \times 70 = 108.78\)។', 'រង្វាស់រង្វាល់', 'pisa', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8335, 'ដែក \(6\) លី \(200\) ដើម និងដែក \(10\) លី \(20\) ដើម (ប្រវែង \(12\ \text{m}\) ម្នាក់ៗ ម៉ាសមាឌ \(7\,874\ \text{kg/m}^3\)) ម៉ាសសរុបប្រហែល (ឱ្យជិត \(1\) kg)៖', NULL, '["\\(534\\ \\text{kg}\\)", "\\(148\\ \\text{kg}\\)", "\\(820\\ \\text{kg}\\)", "\\(682\\ \\text{kg}\\)"]', 3, NULL, 3, 'mcq', '\(200 \times 2.670 + 20 \times 7.417 = 534.04 + 148.35 = 682.4\)។', 'រង្វាស់រង្វាល់', 'pisa', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8336, 'ផ្គរលាន់ឮក្រោយផ្លេកបន្ទោរ \(15\) វិនាទី។ បើសំឡេងធ្វើដំណើរ \(343\ \text{m/s}\) ផ្លេកបន្ទោរនៅឆ្ងាយ៖', NULL, '["\\(0.5145\\ \\text{km}\\)", "\\(51.45\\ \\text{km}\\)", "\\(22.9\\ \\text{km}\\)", "\\(5.145\\ \\text{km}\\)"]', 3, NULL, 3, 'mcq', '\(d = 343 \times 15 = 5\,145\ \text{m}\)។', 'រង្វាស់រង្វាល់', 'pisa', 1, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-091e658f10.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8337, 'គណនាផ្ទៃក្រឡាមុខកាត់ខ្សែភ្លើងអង្កត់ផ្ចិត ក. \(d = 1.5\ \text{mm}\) ខ. \(d = 2\ \text{mm}\) គិតជា \(\text{m}^2\) (\(\pi = 3.14\))។', 'g8-091e658f10.svg', '[]', 0, NULL, 5, 'writing', 'រូបមន្ត \(\mathcal{A} = \dfrac{\pi d^2}{4}\) (1 ពិន្ទុ)
ក. \(d = 1.5 \times 10^{-3}\ \text{m}\) ; \(d^2 = 2.25\times10^{-6}\) (1 ពិន្ទុ)
\(\mathcal{A} = \dfrac{3.14 \times 2.25\times10^{-6}}{4} = 1.76625\times10^{-6}\ \text{m}^2\) (1 ពិន្ទុ)
ខ. \(d^2 = 4\times10^{-6}\) (1 ពិន្ទុ)
\(\mathcal{A} = 3.14\times10^{-6}\ \text{m}^2\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'easy', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8338, 'គណនាមាឌសរសៃដែកគិតជា \(\text{m}^3\) ក. \(d = 6\ \text{mm},\ l = 12\ \text{m}\) ខ. \(d = 16\ \text{mm},\ l = 12\ \text{m}\) (\(\pi = 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្ត \(V = \dfrac{\pi d^2}{4} l\) (1 ពិន្ទុ)
ក. \(\dfrac{3.14 \times 36\times10^{-6}}{4} \times 12\) (1 ពិន្ទុ)
\(= 339.12\times10^{-6} = 3.3912\times10^{-4}\ \text{m}^3\) (1 ពិន្ទុ)
ខ. \(\dfrac{3.14 \times 256\times10^{-6}}{4} \times 12\) (1 ពិន្ទុ)
\(= 2.41152\times10^{-3}\ \text{m}^3\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'medium', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8339, 'ក្រដាសរ៉ាម \(500\) សន្លឹក ខ្នាត \(210\ \text{mm}\times297\ \text{mm}\) ម៉ាសធៀបនឹងផ្ទៃក្រឡា \(80\ \text{g/m}^2\)។ គណនាម៉ាស ១ សន្លឹក និងម៉ាសរ៉ាម ១ ដុំ។', 'g8-7706c08260.svg', '[]', 0, NULL, 5, 'writing', 'ផ្ទៃក្រឡា ១ សន្លឹក \(0.210 \times 0.297 = 0.06237\ \text{m}^2\) (1 ពិន្ទុ)
ម៉ាស ១ សន្លឹក \(0.06237 \times 80 = 4.9896\ \text{g}\) (2 ពិន្ទុ)
ម៉ាស \(500\) សន្លឹក \(500 \times 4.9896 = 2\,494.8\ \text{g}\) (1 ពិន្ទុ)
\(\approx 2.5\ \text{kg}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'medium', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8340, 'ក. រថភ្លើងធ្វើដំណើរ \(3\) ម៉ោង ល្បឿន \(30\ \text{km/h}\) ចម្ងាយប៉ុន្មាន? ខ. ដោយល្បឿនដដែល ធ្វើដំណើរ \(500\ \text{m}\) ប្រើពេលប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(d = v \times t = 30 \times 3\) (1 ពិន្ទុ)
\(= 90\ \text{km}\) (1 ពិន្ទុ)
ខ. \(500\ \text{m} = 0.5\ \text{km}\) (1 ពិន្ទុ)
\(t = \dfrac{0.5}{30} = \dfrac{1}{60}\ \text{h}\) (1 ពិន្ទុ)
\(= 1\ \text{mn} = 60\ \text{s}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'medium', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8341, 'ឈើជ្រុងមួយដើមមានមុខកាត់ \(4\ \text{cm} \times 8\ \text{cm}\) ប្រវែង \(4.5\ \text{m}\)។ ទិញ \(50\) ដើម ឈើ \(1\ \text{m}^3\) ថ្លៃ \(1\,200\,000\) ៛។ ត្រូវចំណាយប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរខ្នាត \(4\ \text{cm} = 0.04\ \text{m}\) ; \(8\ \text{cm} = 0.08\ \text{m}\) (1 ពិន្ទុ)
មាឌ ១ ដើម \(0.04 \times 0.08 \times 4.5 = 0.0144\ \text{m}^3\) (1 ពិន្ទុ)
មាឌ \(50\) ដើម \(50 \times 0.0144 = 0.72\ \text{m}^3\) (1 ពិន្ទុ)
\(0.72 \times 1\,200\,000\) (1 ពិន្ទុ)
\(= 864\,000\) ៛ (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'medium', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8342, 'ដែក \(10\) លីមួយដើមមានម៉ាស \(7.4\ \text{kg}\)។ រកម៉ាសដែក \(16\) លី (ប្រវែងដូចគ្នា ម៉ាសមាឌដូចគ្នា)។', NULL, '[]', 0, NULL, 5, 'writing', 'ម៉ាសសមាមាត្រនឹងផ្ទៃក្រឡាមុខកាត់ ឬ \(d^2\) (1 ពិន្ទុ)
\(\dfrac{m_{16}}{m_{10}} = \left(\dfrac{16}{10}\right)^2 = 2.56\) (2 ពិន្ទុ)
\(m_{16} = 2.56 \times 7.4\) (1 ពិន្ទុ)
\(= 18.944\ \text{kg}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'hard', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8343, 'វិបុលជិះកង់ \(26\ \text{km}\) ក្នុងរយៈពេល \(41\ \text{mn}\ 52\ \text{s}\)។ រកល្បឿនមធ្យមគិតជា \(\text{km/h}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរជាវិនាទី \(41 \times 60 + 52 = 2\,512\ \text{s}\) (1 ពិន្ទុ)
ប្តូរជាម៉ោង \(\dfrac{2\,512}{3\,600} = \dfrac{157}{225}\ \text{h}\) (1 ពិន្ទុ)
\(v = \dfrac{26}{157/225} = \dfrac{26 \times 225}{157}\) (2 ពិន្ទុ)
\(\approx 37.26\ \text{km/h}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'hard', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8344, 'ខ្សែស្ពាន់ប្រវែង \(100\ \text{m}\) មុខកាត់អង្កត់ផ្ចិត \(2.5\ \text{mm}\) ម៉ាសមាឌ \(8.94\ \text{g/cm}^3\)។ គណនាម៉ាស (\(\pi = 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរខ្នាត \(d = 0.25\ \text{cm}\) ; \(l = 10\,000\ \text{cm}\) (1 ពិន្ទុ)
\(V = \dfrac{3.14 \times 0.25^2}{4} \times 10\,000\) (1 ពិន្ទុ)
\(= 490.625\ \text{cm}^3\) (1 ពិន្ទុ)
\(m = 490.625 \times 8.94 = 4\,386.19\ \text{g}\) (1 ពិន្ទុ)
\(\approx 4.39\ \text{kg}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'hard', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8345, 'រតនានៅចម្ងាយ \(800\ \text{m}\) ពីសាលា ដើរល្បឿន \(5\ \text{km/h}\)។ ត្រូវដល់សាលា \(15\) នាទីមុនម៉ោង \(7\ \text{h}\ 00\)។ ត្រូវចេញពីផ្ទះម៉ោងប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ចម្ងាយ \(0.8\ \text{km}\) (1 ពិន្ទុ)
រយៈពេលដើរ \(t = \dfrac{0.8}{5} = 0.16\ \text{h} = 9.6\ \text{mn} = 9\ \text{mn}\ 36\ \text{s}\) (2 ពិន្ទុ)
ម៉ោងត្រូវដល់ \(7\ \text{h}\ 00 - 15\ \text{mn} = 6\ \text{h}\ 45\ \text{mn}\) (1 ពិន្ទុ)
ម៉ោងចេញ \(6\ \text{h}\ 45\ \text{mn} - 9\ \text{mn}\ 36\ \text{s} = 6\ \text{h}\ 35\ \text{mn}\ 24\ \text{s}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'hard', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8346, 'ដែក \(10\) លី \(12\) លី និង \(14\) លី ប្រវែង \(12\ \text{m}\) ម៉ាសមាឌ \(7\,874\ \text{kg/m}^3\) (\(\pi = 3.14\))។ គណនាម៉ាសដែកមួយដើមនីមួយៗ (ទសភាគ ១ ខ្ទង់)។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្ត \(m = \dfrac{\pi d^2}{4} \cdot l \cdot \mu\) (1 ពិន្ទុ)
ដែក ១០ លី \(d = 0.01\ \text{m}\) \(m \approx 7.4\ \text{kg}\) (1 ពិន្ទុ)
ដែក ១២ លី \(d = 0.012\ \text{m}\) \(m \approx 10.7\ \text{kg}\) (1 ពិន្ទុ)
ដែក ១៤ លី \(d = 0.014\ \text{m}\) \(m \approx 14.5\ \text{kg}\) (1 ពិន្ទុ)
បង្ហាញការជំនួស \(\dfrac{3.14 \times 144\times10^{-6}}{4} \times 12 \times 7\,874\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'pisa', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8347, 'ពូសុខទិញដែក \(6\) លី \(200\) ដើម និងដែក \(10\) លី \(20\) ដើម ប្រវែង \(12\ \text{m}\) ម្នាក់ៗ។ ដែក \(1\ \text{kg}\) ថ្លៃ \(2\,800\) ៛ ម៉ាសមាឌ \(7\,874\ \text{kg/m}^3\)។ គណនាប្រាក់ត្រូវចំណាយ (\(\pi=3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ម៉ាសដែក ៦ លី ១ ដើម \(\dfrac{3.14 \times 36\times10^{-6}}{4} \times 12 \times 7\,874 \approx 2.67\ \text{kg}\) (1 ពិន្ទុ)
\(200 \times 2.670 = 534.04\ \text{kg}\) (1 ពិន្ទុ)
ម៉ាសដែក ១០ លី ២០ ដើម \(20 \times 7.417 = 148.35\ \text{kg}\) (1 ពិន្ទុ)
ម៉ាសសរុប \(682.4\ \text{kg}\) (1 ពិន្ទុ)
\(682.4 \times 2\,800 \approx 1\,910\,700\) ៛ (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'pisa', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8348, 'ក្រដាសខ្នាតធំ \(80\ \text{g/m}^2\) កាត់ជារ៉ាម \(210\ \text{mm}\times297\ \text{mm}\) (\(500\) សន្លឹក) ខាតចំនៀរ \(4\%\) (បន្ថែម \(4\%\) លើម៉ាសរ៉ាម)។ ក. រកម៉ាសរ៉ាម ១ ដុំ។ ខ. រកម៉ាសក្រដាសត្រូវការសម្រាប់ ១ រ៉ាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(500 \times 0.06237 \times 0.080 = 2.4948\ \text{kg}\) (2 ពិន្ទុ)
ខ. ខាត \(4\%\) \(2.4948 \times 1.04\) (2 ពិន្ទុ)
\(= 2.594592\ \text{kg} \approx 2.6\ \text{kg}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'pisa', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8349, 'សៀវភៅមួយក្បាល \(100\) ទំព័រ ខ្នាត \(148\ \text{mm}\times210\ \text{mm}\) សាច់ក្នុងក្រដាស \(70\ \text{g/m}^2\) (\(50\) សន្លឹក) ក្របក្រដាស \(150\ \text{g/m}^2\) (សន្លឹក ១ ទំហំពីរទំព័រ)។ គណនាម៉ាសក្រដាសសរុបក្នុង ១ ក្បាល។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ទៃក្រឡា ១ ទំព័រ \(0.148 \times 0.210 = 0.03108\ \text{m}^2\) (1 ពិន្ទុ)
សាច់ក្នុង \(50 \times 0.03108 \times 70 = 108.78\ \text{g}\) (2 ពិន្ទុ)
ក្រប \(2 \times 0.03108 \times 150 = 9.324\ \text{g}\) (1 ពិន្ទុ)
\(108.78 + 9.324 = 118.104\ \text{g}\) (1 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'pisa', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8350, 'ក. ពពកមួយរសាត់ពីព្រះសីហនុមកភ្នំពេញ ចម្ងាយ \(230\ \text{km}\) ខ្យល់ល្បឿន \(6\ \text{m/s}\)។ ប្តូរល្បឿនជា \(\text{km/h}\) រួចរករយៈពេល។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរល្បឿន \(6\ \text{m/s} = 6 \times 3.6 = 21.6\ \text{km/h}\) (2 ពិន្ទុ)
រយៈពេល \(t = \dfrac{d}{v} = \dfrac{230}{21.6} = \dfrac{575}{54}\ \text{h}\) (1 ពិន្ទុ)
\(= 10\dfrac{35}{54}\ \text{h} \approx 10\ \text{h}\ 39\ \text{mn}\) (2 ពិន្ទុ)', 'រង្វាស់រង្វាល់', 'pisa', 0, '8', 'រង្វាស់រង្វាល់', NULL, 0);
